// How do I pin a chosen block of rows and columns in place during scrolling in a spreadsheet?

// Keep a defined region always on screen by anchoring it to the corner of the view in a spreadsheet.

let worksheet = Api.GetActiveSheet();
let freezePanes = worksheet.GetFreezePanes();
let range = Api.GetRange('H2:K4');
freezePanes.FreezeAt(range);

// How do I stop columns from moving out of view when scrolling horizontally in a spreadsheet?

// Pin the leading columns in place to keep key labels visible at all times in a spreadsheet.

let worksheet = Api.GetActiveSheet();
let freezePanes = worksheet.GetFreezePanes();
freezePanes.FreezeColumns(1);

// How do I keep header rows from disappearing when scrolling through data in a spreadsheet?

// Pin the uppermost rows in place so column labels are always on screen in a spreadsheet.

let worksheet = Api.GetActiveSheet();
let freezePanes = worksheet.GetFreezePanes();
freezePanes.FreezeRows(1);

// How do I find out which rows or columns are currently locked in place in a spreadsheet?

// Retrieve the cell reference of the frozen region to confirm what is pinned in a spreadsheet.

Api.SetFreezePanesType('column');
let worksheet = Api.GetActiveSheet();
let freezePanes = worksheet.GetFreezePanes();
let range = freezePanes.GetLocation();
worksheet.GetRange("A1").SetValue("Location: ");
worksheet.GetRange("B1").SetValue(range.GetAddress());

// How do I remove frozen panes and allow the entire sheet to scroll without restrictions in a spreadsheet?

// Unpin any fixed areas to restore normal scrolling behavior across the whole sheet in a spreadsheet.

Api.SetFreezePanesType('column');
let worksheet = Api.GetActiveSheet();
let freezePanes = worksheet.GetFreezePanes();
freezePanes.Unfreeze();
let range = freezePanes.GetLocation();
worksheet.GetRange("A1").SetValue("Location: ");
worksheet.GetRange("B1").SetValue(range + "");
